#include "dependencies/counting.hpp"
I onto(int n,int q){vector<vector<I>> d(n+1,vector<I>(q+1));d[0][0]=1;for(int i=1;i<=n;i++)for(int j=1;j<=q;j++)d[i][j]=j*(d[i-1][j]+d[i-1][j-1]);return d[n][q];}
G expand(const G&pat,int c,const vector<int>&lens){vector<int>types;for(int i=0;i<c;i++)types.push_back(i);for(int i=0;i<(int)lens.size();i++)for(int j=0;j<lens[i];j++)types.push_back(c+i);G a(types.size());for(int i=0;i<(int)a.size();i++)for(int j=i+1;j<(int)a.size();j++){if(types[i]==types[j]||(pat[types[i]]>>types[j]&1))a[i]|=1<<j;else a[j]|=1<<i;}return a;}
vector<vector<int>> skeletons(const G&pat,int c,int r){vector<vector<int>> res;vector<int>ord(c);iota(ord.begin(),ord.end(),0);do{vector<int>gaps(c+1);function<void(int)>go=[&](int g){if(g<=c){for(int S=0;S<(1<<r);S++){gaps[g]=S;go(g+1);}return;}vector<int>seq,q(r);for(int k=0;k<=c;k++){for(int i=0;i<r;i++)if(gaps[k]>>i&1){seq.push_back(c+i);q[i]++;}if(k<c)seq.push_back(ord[k]);}for(int i=1;i<(int)seq.size();i++)if(!(pat[seq[i-1]]>>seq[i]&1))return;res.push_back(q);};go(0);}while(next_permutation(ord.begin(),ord.end()));return res;}
int main(){I sourceRoots=0,unique=0,multi=0,templates=0,graphs=0,normalizations=0;for(int n=2;n<=6;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){G a=graph(n,code);Counts c(a);for(int v=0;v<n;v++){auto[h,s,e,L,R,d,b,B,D]=c.profile(v);if(!s)continue;sourceRoots++;int k=__builtin_popcount((unsigned)a[v]);if(k>=2){multi++;need(D>=s+(k-1)*d&&d<=D&&k<=D,"multiple outgoing reduction");}else if(n>2){unique++;int w=__builtin_ctz((unsigned)a[v]),T=c.F^(1<<v)^(1<<w),Iset=T^(a[w]&T),m=__builtin_popcount((unsigned)Iset);I ends=0,starts=0,K=0;for(int x=0;x<n;x++)if(Iset>>x&1){ends+=c.en[T*n+x];starts+=c.st[T*n+x];}for(int A=T;;A=(A-1)&T){int P=T^A;if(A&&P)for(int x=0;x<n;x++)if(Iset>>x&1)for(int y=0;y<n;y++)if(Iset>>y&1)K+=c.en[A*n+x]*c.st[P*n+y];if(!A)break;}need(s==c.H[T]-starts&&D==c.H[T]+2*ends+K&&K>=m*(m-1)/2&&c.H[T]<=D&&m<=D,"single outgoing reduction");}else need(B==1&&D==3,"edge boundary");}}
 for(int c=0;c<=3;c++)for(int r=0;r<=2;r++){if(c==3&&r==2)continue;for(int cc=0;cc<(1<<(c*(c-1)/2));cc++)for(int cross=0;cross<(1<<(c*r));cross++){
  G core=graph(c,cc),pat(c+r);for(int i=0;i<c;i++)pat[i]=core[i];for(int i=0;i<r;i++)for(int j=i+1;j<r;j++)pat[c+i]|=1<<(c+j);for(int i=0;i<c;i++)for(int j=0;j<r;j++){if(cross>>(i*r+j)&1)pat[i]|=1<<(c+j);else pat[c+j]|=1<<i;}
  auto sk=skeletons(pat,c,r);templates++;vector<int>lens(r);function<void(int)>go=[&](int at){if(at<r){for(int n=0;n<=3;n++){lens[at]=n;go(at+1);}return;}I formula=0;for(auto q:sk){I t=1;for(int i=0;i<r;i++)t*=onto(lens[i],q[i]);formula+=t;}Counts literal(expand(pat,c,lens));need(formula==literal.h(),"positive skeleton count");graphs++;};go(0);
  if(r==1&&c<=2){for(int n=4;n<=10;n++){vector<int>ns{n};I val=0;for(auto q:sk)val+=onto(n,q[0]);int lg=0;while((1LL<<(lg+1))<=val)lg++;int N=lg+c+1;if(n>N){I reduced=0;for(auto q:sk)reduced+=onto(N,q[0]);need(reduced==val,"long invisible run normalization");normalizations++;}}}
 }}
 cout<<"{\n  \"status\": \"PASS\",\n  \"positive_rooted_inputs\": "<<sourceRoots<<",\n  \"one_outneighbor_nonedge_inputs\": "<<unique<<",\n  \"multiple_outneighbor_inputs\": "<<multi<<",\n  \"chain_templates\": "<<templates<<",\n  \"literal_expansions\": "<<graphs<<",\n  \"long_run_normalizations\": "<<normalizations<<"\n}\n";
}
